import {publicEvidence} from './public-sources-data.mjs?v=20261023-final-1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function publicSourcesPage(){return `<section class="public-sources"><button class="back-button" data-action="quick-new">← К проверке</button><div class="page-heading"><div><h1>Механика важнее суммы.</h1><p>12 первичных справочных источников. Проверены 20 октября 2026 года.</p></div><a class="button secondary" href="./public-evidence-sources.json" download>Каталог JSON</a></div><section class="method-intro"><h2>Почему нужна проверка контекста</h2><p>Деньги рядом с призом и рандомайзером могут означать стоимость подарка, доставку или использование купона. Отдельно проверяйте, обязательна ли оплата именно для участия.</p><p>Ниже наши короткие пересказы с указанием происхождения. Это справочные материалы; они не входят в замер точности и не являются точными цитатами исходных соцпостов.</p></section><h2>Опубликованные механики</h2><div class="public-source-grid">${publicEvidence.sources.filter(s=>!s.category.includes('api')&&!s.id.startsWith('meta-')&&!s.id.startsWith('tiktok-')).map(s=>`<article class="method-card"><span class="network-pill">${s.content_origin==='official_summary'?'Официальный пересказ':'Условия / сообщение организатора'}</span><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p><details><summary>Что можно и нельзя заключить</summary><p><strong>Подтверждает:</strong> ${esc(s.confirms)}</p><p><strong>Не подтверждает:</strong> ${esc(s.does_not_confirm)}</p><p class="section-sub">${esc(s.date_note)} ${s.access?.includes('403')?'Прямое чтение ограничено; использован индексированный фрагмент официального домена.':''}</p></details><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.publisher)} ↗</a></article>`).join('')}</div><h2>Получение материалов из соцсетей</h2><section class="method-card"><p>Сейчас ІЗ принимает вручную добавленные тексты, скриншоты и JSON из разрешённого источника. Вставленная ссылка сохраняется для сверки; содержимое по ней не скачивается.</p><p>TikTok Display API требует разрешения владельца аккаунта и одобрения приложения. Research Tools имеют отдельные условия доступа; доступ команды из Казахстана не подтверждён. Meta API также не даёт произвольного доступа ко всем профилям. Обходов ограничений в проекте нет.</p><ul>${publicEvidence.sources.filter(s=>s.id.startsWith('meta-')||s.id.startsWith('tiktok-')).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a> — ${esc(s.summary)}</li>`).join('')}</ul></section><section class="about-limits"><h2>Следующий этап проверки</h2><p>Для оценки на реальных публикациях нужен разрешённый обезличенный корпус с полными условиями, независимая разметка специалистов и отдельная свежая выборка. Открытая страница не означает разрешение на массовый сбор или копирование.</p></section></section>`;}
